+import '../../../skinned-sdk';
+import React from 'react';
+import { renderIntoDocument } from 'react-dom/test-utils';
+import ExternalLink from '../../../../src/components/views/elements/ExternalLink';
+
+describe('<ExternalLink />', () => {
+    it('keeps the link text, announces the new tab, and hides its decorative icon', () => {
+        const wrapper = renderIntoDocument<HTMLSpanElement>(
+            <span>
+                <ExternalLink href="https://example.org" className="custom-link" title="Example site">
+                    Example site
+                </ExternalLink>
+            </span>,
+        ) as HTMLSpanElement;
+        const link = wrapper.querySelector('a');
+
+        expect(link.classList.contains('mx_ExternalLink')).toBe(true);
+        expect(link.classList.contains('custom-link')).toBe(true);
+        expect(link.href).toBe('https://example.org/');
+        expect(link.target).toBe('_blank');
+        expect(link.rel).toBe('noreferrer noopener');
+        expect(link.title).toBe('Example site');
+        expect(link.textContent).toContain('Example site');
+        expect(link.textContent).toContain('Opens in a new tab');
+        expect(link.querySelector('.mx_ExternalLink_icon').getAttribute('aria-hidden')).toBe('true');
+    });
+});
